<script module lang="ts">
/**
 * A preview card shown on hover or focus (`design/components/hover-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hover-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import * as zag from '@zag-js/hover-card'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  anchorProps,
  attributes,
  devWarning,
  joinSlot,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/hover-card.module.css'

export type HoverCardSide = NonNullable<HoverCardProps['side']>

export type HoverCardAlign = NonNullable<HoverCardProps['align']>

export interface HoverCardProps {
  align?: 'start' | 'center' | 'end'
  /**
   * The trigger: one focusable element with its own destination or action, which the card
   * previews but never replaces. A HoverCard on an inert span previews nothing reachable.
   */
  children: Snippet
  /**
   * Vocabulary content, typically a Stack of Avatar/Text/Badge rows. It has no typed shape,
   * because person, ticket and link previews share no anatomy and the closed vocabulary already
   * constrains it. The never-load-bearing law governs the content, not a slot shape.
   */
  content: Snippet
  /**
   * Opens on mount, for galleries and tests; screens wait for the reader to hover.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}
</script>

<script lang="ts">
let { align = 'start', children, content, defaultOpen, side = 'bottom' }: HoverCardProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let panel = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen,
      openDelay: TOOLTIP_DELAY_MS,
      closeDelay: TOOLTIP_SKIP_DELAY_MS,
      positioning: {
        placement: align === 'center' ? side : `${side}-${align}`,
        offset: { mainAxis: 4 },
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open,
  () => panel,
)
const effect1 = () => {
  devWarning(
    api.open &&
      panel?.querySelector(
        'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])',
      ) != null,
    'HoverCard: the preview contains interactive content, which keyboard and touch readers can never reach. A card the reader must operate is a Popover.',
  )
}
watchEffect(effect1, { watch: () => api.open })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span {...attributes(anchorProps(api.getTriggerProps()))} class={styles.anchor}
    >{@render children?.()
  }</span
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.panel}
          hidden={undefined}
          data-member="hover-card"
          >{@render content?.()
        }</div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
